while let Some(chunk) = response.chunk().await? {
    file.write_all(&chunk).await?;
    downloaded_bytes += chunk.len() as u64;

    // ... cálculo de velocidade
    app_handle.emit("download_message", ...);       // ❌ muito frequente
    app_handle.emit("download_info", ...);          // ❌ muito frequente
    app_handle.emit("download_speed", ...);         // ❌ muito frequente
}

// ✅ Depois: throttle os emits
let mut last_emit_time = Instant::now();

while let Some(chunk) = response.chunk().await? {
    file.write_all(&chunk).await?;
    downloaded_bytes += chunk.len() as u64;

    // Emit apenas quando necessário ou periodicamente
    let elapsed_ms = start_time.elapsed().as_secs_f64() * 1000.0;
    if elapsed_ms >= 100.0 { // A cada 100ms máximo
        // envia apenas atualizações relevantes
    }
}
```

